def check_graph(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check degrees
    for i in range(n):
        if not (3 <= len(adj[i]) <= 4):
            return False, f"Vertex {i} has degree {len(adj[i])}"

    # Check girth
    for start_node in range(n):
        queue = [(start_node, -1, 0)]
        visited = {start_node: 0}
        while queue:
            u, p, d = queue.pop(0)
            if d >= 5:
                continue
            for v in adj[u]:
                if v == p:
                    continue
                if v in visited:
                    if visited[v] + d + 1 < 6:
                        return False, f"Cycle of length {visited[v] + d + 1} found"
                else:
                    visited[v] = d + 1
                    queue.append((v, u, d + 1))
    return True, "OK"

edges = [(6, 0), (10, 13), (8, 15), (4, 16), (9, 17), (2, 0), (9, 18), (10, 16), (15, 16), (13, 12), (18, 22), (7, 6), (8, 18), (14, 15), (13, 9), (21, 10), (1, 0), (2, 3), (20, 4), (2, 19), (14, 7), (1, 12), (11, 12), (1, 5), (14, 19), (21, 22), (6, 20), (19, 22), (8, 3), (5, 21), (17, 5), (11, 7), (22, 20), (4, 17), (3, 11)]
